package com.careerorbit.service;
import com.careerorbit.entity.UserEntity;import com.careerorbit.mapper.UserMapper;import com.careerorbit.security.JwtService;import com.careerorbit.common.BusinessException;import org.junit.jupiter.api.Test;import org.springframework.security.crypto.password.PasswordEncoder;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class AuthServiceTest {@Test void registerRejectsDuplicateEmail(){var users=mock(UserMapper.class);when(users.selectOne(any())).thenReturn(user());var service=new AuthService(users,mock(PasswordEncoder.class),mock(JwtService.class));assertThatThrownBy(()->service.register("used@example.com","password123","测试用户")).isInstanceOf(BusinessException.class).hasMessageContaining("已注册");}@Test void loginRejectsWrongPasswordWithoutIssuingToken(){var users=mock(UserMapper.class);var encoder=mock(PasswordEncoder.class);var jwt=mock(JwtService.class);when(users.selectOne(any())).thenReturn(user());when(encoder.matches(anyString(),anyString())).thenReturn(false);assertThatThrownBy(()->new AuthService(users,encoder,jwt).login("used@example.com","wrong")).isInstanceOf(BusinessException.class).hasMessage("邮箱或密码错误");verifyNoInteractions(jwt);}private UserEntity user(){var u=new UserEntity();u.id=1L;u.email="used@example.com";u.passwordHash="hash";u.displayName="测试用户";u.role="USER";return u;}}
